NEW_FILES = {'documentation/smoke_drawn_ends.js': '// smoke_drawn_ends.js -- every drawing in the Sun and Earth rooms starts\n// and stops where a served row says it does (L-460).\n//\n// RUN:  node documentation/smoke_drawn_ends.js   (gallery root)\n//\n// WHY THIS EXISTS\n//   On 2026-10-21 the corona was found drawn from the Sun\'s surface,\n//   under the chromosphere, while the paper its dots follow puts the base\n//   of the corona 3,000 km higher. Nothing had checked where a drawing\n//   ENDS against the rows behind it. Tony: "we should double check our\n//   drawings for correct distances", and the check belongs where it runs\n//   (A Check That Cannot Fail Is Not Passing). The rule is in\n//   provenance-discipline 2.33, What a Visitor Reads, principle 4.\n//\n// WHAT IT CHECKS\n//   Both rooms are built with the real renderers from the served config\n//   and the served cache\'s stored drawings, as the page builds them (the\n//   Earth room on its recorded scene with the config\'s Earth rows). For\n//   every served shell, the nearest and the farthest point drawn are\n//   measured from the centre, leaving out the info marker and any point\n//   drawn with no opacity. Each end must match a length on the shell\'s\n//   own served row, within MATCH (half a percent; the stored drawings\n//   round each coordinate, and a dot drawn at random sits just inside its\n//   edge). The body\'s own radius is not a row of the shell: an end that\n//   only meets the Sun\'s or Earth\'s surface is not explained by it.\n//   An end that matches no row passes only if it is on HELD, with its\n//   reason and the distance it was measured at; if it moves by more than\n//   HELD_DRIFT (a tenth of a percent) from that distance, it fails too,\n//   so a held end cannot drift\n//   unseen. Every held end is printed every run, so an addition shows.\n//\n// WHAT MAKES IT FAIL\n//   An end that matches no row and is not held, or a held end that has\n//   moved, named by room, shell and end. A SELF-TEST plants two faults\n//   first and must go red on both: the corona\'s dots moved back to the\n//   Sun\'s surface, and one Hills cloud dot moved to 257 AU.\n//\n// Module written: October 21, 2026 with Anthropic\'s Claude Opus 5.5 (new,\n// L-460).\n//\n// Role: devtool\n// Domain: dev_tools\n\n"use strict";\nconst fs = require("fs");\nconst path = require("path");\nconst ROOT = path.join(__dirname, "..");\nfunction read(rel) { return fs.readFileSync(path.join(ROOT, rel), "utf8"); }\n\nconst MATCH = 0.005;\n// A held end is measured on a seeded or stored drawing, so it does not\n// move between runs; a tenth of a percent is the stored files\' rounding.\nconst HELD_DRIFT = 0.001;\n\n// Ends no row sets, each with why and where it was measured (AU, from the\n// centre), at gallery 72c3c403 with the orrery\'s drawings of 2026-10-21.\n// Adding one is a ruling: it says this end is right although no row says\n// so. Remove one when its row arrives or its drawing is fixed.\nconst HELD = [\n  ["sun", "Sun: Corona", "near", 0.00466907,\n   "the corona\'s base: its row \'base\' is a height, 3,000 km above the " +\n   "visible surface (Mann et al. 2023), not a distance from the centre"],\n  ["sun", "Sun: Zodiacal Dust Cloud (F-corona)", "near", 0.0249323,\n   "sampling: the dust thins to nothing at the dust-free zone, 5 solar " +\n   "radii (its row free_zone), so few dots fall near it"],\n  ["sun", "Sun: Hills Cloud (tilted disk)", "far", 19281.2,\n   "sampling: the disk thins to nothing by 20,000 AU (its row " +\n   "outer_radius)"],\n  ["sun", "Sun: Outer Oort Cloud (clumps)", "near", 21363,\n   "OPEN, L-434: 15 clumps placed at random; none reaches the 10,000 AU " +\n   "where its row says the clumps begin. Fixed when the clumps become a " +\n   "stored drawing"],\n  ["sun", "Sun: Galactic Tide (sparse at the plane and poles)", "near", 10563,\n   "sampling: the tide begins thin at 10,000 AU (its row inner_radius)"],\n  ["earth", "Earth: Magnetopause", "far", 0.000994511,\n   "where the fitted surface is cut, at its served cut angle (a row, in " +\n   "degrees)"],\n  ["earth", "Earth: Bow Shock", "far", 0.00127882,\n   "where the fitted surface is cut, at its served cut angle (a row, in " +\n   "degrees)"],\n  ["earth", "Earth: Magnetotail", "near", 0.00130338,\n   "where the page continues the magnetopause from its cut; the row says " +\n   "so"],\n  ["earth", "Earth: Magnetotail", "far", 0.00946655,\n   "the rim of its far end: drawn_end (220 Earth radii) along the tail, " +\n   "drawn_radius (30) out from its axis"],\n  ["earth", "Earth: Inner Radiation Belt", "near", 0.0000432994,\n   "OPEN, Earth\'s slice: the dots follow the dipole field lines from the " +\n   "belt\'s equatorial edges down to the ground; no row says how far down " +\n   "the trapped particles reach"],\n  ["earth", "Earth: Outer Radiation Belt", "near", 0.0000672407,\n   "OPEN, Earth\'s slice: as the inner belt"],\n];\n\nconst failures = [];\nfunction fail(m) { failures.push(m); }\n\nglobal.window = global;\neval(read("gallery/feature_renderers.js"));\neval(read("gallery/earth_geometry.js"));\nconst GF = global.GalleryFeatures;\nconst EG = global.EarthGeometry;\nconst coverage = JSON.parse(read("data/solar-system/coverage_index.json"));\nconst notes = GF.setFrameConstants(coverage.frame_constants);\nif (notes.length) fail("frame constants not served: " + notes.join("; "));\nconst KM_PER_AU = coverage.frame_constants.rows.KM_PER_AU.value;\nfunction loadDrawings() {\n  const dir = path.join(ROOT, "data", "solar-system", "drawings");\n  const map = {};\n  fs.readdirSync(dir).filter(n => /\\.json$/.test(n)).forEach(n => {\n    map[n.slice(0, -5)] = JSON.parse(fs.readFileSync(path.join(dir, n), "utf8"));\n  });\n  return map;\n}\nconst config = JSON.parse(read("data/objects_config.json"));\nfunction featuresOf(slug) {\n  const o = (config.objects || []).find(x => x && x.slug === slug);\n  return Object.keys(o.features).map(k => ({ object: slug, feature: k, params: o.features[k] }));\n}\n\nfunction build(drawings) {\n  GF.setDrawings(drawings);\n  const sun = { traces: GF.buildFeatureTraces(featuresOf("sun"),\n    { sun: { name: "Sun", position: [0, 0, 0] } }, { sceneHalfRangeAu: 0.25 }).traces,\n    features: featuresOf("sun") };\n  const p = JSON.parse(read("documentation/payload_earth_scene.json"));\n  p.features = featuresOf("earth");\n  const earth = { traces: EG.composeScene(p, { GF: GF, halfRangeAu: 6.155e-5,\n    epochIso: "x" }).traces, features: p.features };\n  return { sun: sun, earth: earth };\n}\n\nfunction alpha(c) {\n  const m = /rgba\\([^)]*,\\s*([0-9.]+)\\)$/.exec(String(c || ""));\n  return m ? parseFloat(m[1]) : 1;\n}\nfunction rowFor(features, key) {\n  for (const fr of features) {\n    if (fr.params && fr.params[key] && typeof fr.params[key] === "object") {\n      return { row: fr.params[key], group: fr.params };\n    }\n  }\n  for (const fr of features) if (fr.feature === key) return { row: fr.params, group: fr.params };\n  return null;\n}\nfunction lengths(node, group, out) {\n  if (!node || typeof node !== "object") return out;\n  if (typeof node.value === "number" && typeof node.unit === "string") {\n    const b = group.sun_radius || group.planet_radius;\n    const bk = b && b.value;\n    let au = null;\n    if (node.unit === "au") au = node.value;\n    else if (node.unit === "km") au = node.value / KM_PER_AU;\n    else if ((node.unit === "r_sun" || node.unit === "r_earth") && bk) au = node.value * bk / KM_PER_AU;\n    if (au !== null) out.push(au);\n    return out;\n  }\n  for (const k of Object.keys(node)) {\n    if (k === "in" || k === "sun_radius" || k === "planet_radius") continue;\n    lengths(node[k], group, out);\n  }\n  return out;\n}\n\nfunction ends(room) {\n  const groups = {}, order = [];\n  room.traces.forEach(t => {\n    if (!t.meta || !t.meta.shell_key) return;\n    const n = (t.x || []).length;\n    if (n <= 1) return;\n    const k = t.legendgroup;\n    if (!groups[k]) { groups[k] = { shell: t.meta.shell_key, near: Infinity, far: 0 }; order.push(k); }\n    const cols = t.marker && Array.isArray(t.marker.color) ? t.marker.color : null;\n    for (let j = 0; j < n; j++) {\n      if (cols && alpha(cols[j]) === 0) continue;\n      const r = Math.hypot(t.x[j], t.y[j], t.z[j]);\n      if (!isFinite(r)) continue;\n      if (r < groups[k].near) groups[k].near = r;\n      if (r > groups[k].far) groups[k].far = r;\n    }\n  });\n  return order.map(k => Object.assign({ name: k }, groups[k]));\n}\n\nfunction judge(built) {\n  const bad = [], held = [];\n  let checked = 0, matched = 0;\n  for (const roomName of ["sun", "earth"]) {\n    const room = built[roomName];\n    for (const g of ends(room)) {\n      const served = rowFor(room.features, g.shell);\n      const L = served ? lengths(served.row, served.group, []) : [];\n      for (const which of ["near", "far"]) {\n        const v = g[which];\n        checked += 1;\n        if (L.some(x => Math.abs(x - v) / v <= MATCH)) { matched += 1; continue; }\n        const h = HELD.find(e => e[0] === roomName && e[1] === g.name && e[2] === which);\n        if (!h) {\n          bad.push(roomName + ": " + g.name + ", its " + which + " end at " +\n                   v.toPrecision(6) + " AU, matches no length on its served row " +\n                   "and is not held");\n        } else if (Math.abs(h[3] - v) / h[3] > HELD_DRIFT) {\n          bad.push(roomName + ": " + g.name + ", its held " + which + " end moved, " +\n                   h[3] + " AU when held, " + v.toPrecision(6) + " AU now");\n        } else {\n          held.push(h);\n        }\n      }\n    }\n  }\n  return { bad: bad, held: held, checked: checked, matched: matched };\n}\n\n// --- self-test --------------------------------------------------------\n(function selfTest() {\n  const surface = loadDrawings();\n  const c = surface.sun_corona;\n  const r0 = Math.hypot(c.x[0], c.y[0], c.z[0]);\n  c.x[0] = c.x[0] / r0; c.y[0] = c.y[0] / r0; c.z[0] = c.z[0] / r0;\n  const one = judge(build(surface)).bad.filter(b => /Corona/.test(b));\n  if (!one.length) fail("self-test: a corona dot at the Sun\'s surface stayed green");\n  else console.log("  self-test: a corona dot at the Sun\'s surface -- red: " + one[0]);\n  const near = loadDrawings();\n  near.hills_cloud.x[0] = 257; near.hills_cloud.y[0] = 0; near.hills_cloud.z[0] = 0;\n  const two = judge(build(near)).bad.filter(b => /Hills/.test(b));\n  if (!two.length) fail("self-test: a Hills cloud dot at 257 AU stayed green");\n  else console.log("  self-test: a Hills cloud dot at 257 AU -- red: " + two[0]);\n})();\n\n// --- the rooms ----------------------------------------------------------\nconst r = judge(build(loadDrawings()));\nr.bad.forEach(fail);\nconsole.log("  " + r.checked + " ends measured, " + r.matched + " on a served row, " +\n            r.held.length + " held:");\nr.held.forEach(h => console.log("    " + h[0] + " / " + h[1] + ", " + h[2] + ": " + h[4]));\nconsole.log("");\nif (failures.length) {\n  console.log("=== DRAWN ENDS: " + failures.length + " FAILURE(S)");\n  failures.forEach(f => console.log("  FAIL " + f));\n  process.exit(1);\n}\nconsole.log("=== DRAWN ENDS: every drawing starts and stops on a served row or " +\n            "a held end; self-test red twice");\n', 'documentation/fixture_hovers_L460_on_72c3c403.json': '{\n "sun/Sun: Core": "Sun: Core<br><br>The Sun\'s center, where hydrogen fuses into helium and the Sun\'s light<br soft>and heat are made.<br><br>Radius: 0.25 solar radii<br>= 170,000 km (0.0012 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Radiative Zone": "Sun: Radiative Zone<br><br>The deep layer around the core where energy crawls outward as light,<br soft>absorbed and re-emitted countless times.<br><br>Radius: 0.71 solar radii<br>= 500,000 km (0.00332 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Photosphere": "Sun: Photosphere<br><br>The Sun\'s visible surface: the thin, glowing layer that the light we<br soft>see comes from.<br><br>Radius: 1 solar radius<br>= 695,700 km (0.00465 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Corona": "Sun: Streamer Belt (helmet and stalk)<br><br>The brightest part of the Sun\'s outer atmosphere, seen at a total<br soft>eclipse as the pearly white halo, shaped by the Sun\'s magnetic field.<br><br>Cusp: 4 solar radii<br>= 3,000,000 km (0.02 AU)<br>Helmets reach no higher than 2 to 4 solar radii; drawn at 4.<br>Fades to nothing by: 19.7 solar radii<br>= 13,700,000 km (0.092 AU)<br>Its warp and width are drawn to show the shape, not measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Chromosphere (2,000 km skin)": "Sun: Chromosphere (2,000 km skin)<br><br>A thin, reddish layer of the Sun\'s atmosphere just above the visible<br soft>surface, about 2,000 km deep.<br><br>Radius: 1.003 solar radii<br>= 698,000 km (0.00466 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Roche Limit (Comets)": "Sun: Roche Limit (Comets)<br><br>The distance inside which the Sun\'s tides would pull a loosely held<br soft>comet apart.<br><br>Radius: 3 solar radii<br>= 2,000,000 km (0.02 AU)<br>Known only roughly, because comets differ in density. It is drawn<br soft>where the formula\'s middle answer falls; the true limit could lie a<br soft>little nearer the Sun or farther out.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Alfven Surface": "Sun: Alfven Surface<br><br>The true outer edge of the Sun\'s atmosphere, where the outflowing gas<br soft>becomes the solar wind and can no longer signal back to the Sun.<br><br>Radius: 19.7 solar radii<br>= 13,700,000 km (0.092 AU)<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Corona#2": "Sun: Corona<br><br>The Sun\'s outer atmosphere, a very thin gas of electrons and ions. It<br soft>begins about 3,000 km above the visible surface, just above the<br soft>chromosphere, and has no outer edge. It thins out with height, and at<br soft>the Alfven surface, about 19.7 solar radii (13,700,000 km, 0.092 AU)<br soft>from the Sun\'s center, it becomes the solar wind.<br>Each dot\'s place shows how dense the gas is; its brightness shows how<br soft>much sunlight reaches it.<br>The streamer belt, drawn with it, is the part of the corona where the<br soft>Sun\'s magnetic field closes in loops.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Zodiacal Dust Cloud (F-corona)": "Sun: Zodiacal Dust Cloud (F-corona)<br><br>Dust spread through the inner solar system, flattened toward the plane<br soft>the planets move in. It thins with distance from the Sun and has no<br soft>edge; the drawing stops at 5.2 AU (780,000,000 km).<br>Each dot\'s place shows how dense the dust is; its brightness shows how<br soft>much sunlight reaches it.<br>Near the Sun this dust is seen as the F-corona.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Termination Shock": "Sun: Termination Shock<br><br>The place far beyond the planets where the solar wind slows suddenly<br soft>from supersonic speed as it meets the gas between the stars.<br><br>Radius: 94.01 AU<br>= 14,064,000,000 km<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Heliopause": "Sun: Heliopause<br><br>The outer boundary of the Sun\'s bubble, where the solar wind\'s push is<br soft>balanced by the gas between the stars.<br><br>Radius: 121 AU<br>= 18,100,000,000 km<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Hills Cloud (tilted disk)": "Sun: Hills Cloud (tilted disk)<br><br>The inner part of the Oort cloud: icy bodies far beyond the planets,<br soft>gathered in a slightly warped disk.<br><br>From 2,000 AU (300,000,000,000 km)<br soft>to 10,000 AU (1,000,000,000,000 km),<br soft>thinning out by 20,000 AU (3,000,000,000,000 km).<br>A 2025 computer model (Nesvorny and others) finds the disk tilted<br soft>about 30 degrees to the ecliptic, the plane of Earth\'s orbit, with two<br soft>spiral arms. The dots follow orbits like the model\'s; how stretched<br soft>the orbits are is chosen for the picture.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Outer Oort Cloud (clumps)": "Sun: Outer Oort Cloud (clumps)<br><br>The outer Oort cloud: a rough sphere of icy bodies at the very edge of<br soft>the Sun\'s reach, drawn here as clumps.<br><br>From 10,000 AU (1,000,000,000,000 km),<br soft>filling in by 20,000 AU (3,000,000,000,000 km),<br soft>to 100,000 AU (10,000,000,000,000 km)<br>It begins where the inner cloud\'s disk thins out.<br>Drawn in clumps to show the cloud is not smooth; where the clumps<br soft>really are is not known.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Tide (sparse at the plane and poles)": "Sun: Galactic Tide (sparse at the plane and poles)<br><br>How the Milky Way\'s gravity sends comets in from the outer Oort cloud:<br soft>drawn thickest halfway between the galaxy\'s plane and its poles.<br><br>From 10,000 AU (1,000,000,000,000 km),<br soft>filling in by 20,000 AU (3,000,000,000,000 km),<br soft>to 100,000 AU (10,000,000,000,000 km)<br>Drawn tilted to the galaxy\'s plane; how thick it is at each latitude<br soft>follows how strongly the tide pulls there.<br>Where the comets really are is not known.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane": "Sun: Galactic Plane<br><br>The plane of the Milky Way\'s disk, drawn as a ring around the Sun,<br soft>with a line along the galaxy\'s north-south axis, its two poles marked,<br soft>and the direction of the galaxy\'s centre.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane#2": "North Galactic Pole (NGP)<br>Perpendicular to the disk of our galaxy<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane#3": "South Galactic Pole (SGP)<br>Perpendicular to the disk of our galaxy<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Galactic Plane#4": "Sagittarius A*<br>The direction of the centre of our galaxy, seen from the Sun<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Inner Limit of Oort Cloud": "Sun: Inner Limit of Oort Cloud<br><br>The inner edge of the Oort cloud, where the swarm of icy bodies is<br soft>thought to begin.<br><br>Radius: 2,000 AU<br>= 300,000,000,000 km<br>Thought to lie between 2,000 and 5,000 AU; drawn at 2,000.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Inner Oort Cloud": "Sun: Inner Oort Cloud<br><br>The outer edge of the inner Oort cloud, where the flattened inner<br soft>swarm gives way to the spherical outer cloud.<br><br>Radius: 20,000 AU<br>= 3,000,000,000,000 km<br>The inner cloud gives way to the round outer cloud between 10,000 and<br soft>20,000 AU; this sphere is drawn at 20,000 AU, the far end.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Outer Oort Cloud": "Sun: Outer Oort Cloud<br><br>The outer edge of the Oort cloud, about two light-years from the Sun,<br soft>where the Sun\'s realm gives way to the space between the stars.<br><br>Radius: 100,000 AU<br>= 10,000,000,000,000 km<br>Thought to lie between 10,000 and 100,000 AU; drawn at 100,000.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "sun/Sun: Gravitational Influence": "Sun: Gravitational Influence<br><br>The outer limit of the Sun\'s gravitational hold: how far out a body<br soft>can still belong to the Sun rather than to the galaxy.<br><br>Radius: 134,000 AU<br>= 20,100,000,000,000 km<br>The Sun\'s Hill radius in the galaxy, calculated where the galaxy\'s<br soft>tidal pull overtakes the Sun\'s gravity: about 0.65 parsecs.<br soft>Calculated, not measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Main Ring": "Jupiter: Main Ring<br><br>Inner edge: 122,500 km (0.000819 AU)<br>Outer edge: 129,000 km (0.000862 AU)<br>Thickness: 30 km (2.01e-7 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Halo Ring": "Jupiter: Halo Ring<br><br>Inner edge: 100,000 km (0.000668 AU)<br>Outer edge: 122,500 km (0.000819 AU)<br>Thickness: 12,500 km (0.0000836 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Amalthea Gossamer Ring": "Jupiter: Amalthea Gossamer Ring<br><br>Inner edge: 129,000 km (0.000862 AU)<br>Outer edge: 182,000 km (0.00122 AU)<br>Thickness: 2,000 km (0.0000134 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Thebe Gossamer Ring": "Jupiter: Thebe Gossamer Ring<br><br>Inner edge: 129,000 km (0.000862 AU)<br>Outer edge: 226,000 km (0.00151 AU)<br>Thickness: 8,600 km (0.0000575 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Inner Radiation Belt": "Jupiter: Inner Radiation Belt<br><br>Drawn at 1.5 Jupiter radii<br>= 107,238 km (0.000717 AU)<br>Drawn 0.5 radii wide, a width chosen for the picture.<br>The ring lies in Jupiter\'s equatorial plane, the daily average of the<br soft>magnetic equator, which is tilted from it and turns with Jupiter<br soft>once a day.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Middle Radiation Belt": "Jupiter: Middle Radiation Belt<br><br>Drawn at 3.0 Jupiter radii<br>= 214,476 km (0.00143 AU)<br>Drawn 0.5 radii wide, a width chosen for the picture.<br>The ring lies in Jupiter\'s equatorial plane, the daily average of the<br soft>magnetic equator, which is tilted from it and turns with Jupiter<br soft>once a day.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "jupiter/Jupiter: Outer Radiation Belt": "Jupiter: Outer Radiation Belt<br><br>Drawn at 6.0 Jupiter radii<br>= 428,952 km (0.00287 AU)<br>Drawn 0.5 radii wide, a width chosen for the picture.<br>The ring lies in Jupiter\'s equatorial plane, the daily average of the<br soft>magnetic equator, which is tilted from it and turns with Jupiter<br soft>once a day.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: D Ring": "Saturn: D Ring<br><br>Inner edge: 66,900 km (0.000447 AU)<br>Outer edge: 74,500 km (0.000498 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: C Ring": "Saturn: C Ring<br><br>Inner edge: 74,658 km (0.000499 AU)<br>Outer edge: 92,000 km (0.000615 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: B Ring": "Saturn: B Ring<br><br>Inner edge: 92,000 km (0.000615 AU)<br>Outer edge: 117,500 km (0.000785 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: A Ring": "Saturn: A Ring<br><br>Inner edge: 122,340 km (0.000818 AU)<br>Outer edge: 136,800 km (0.000914 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: F Ring": "Saturn: F Ring<br><br>Inner edge: 140,210 km (0.000937 AU)<br>Outer edge: 140,420 km (0.000939 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: G Ring": "Saturn: G Ring<br><br>Inner edge: 166,000 km (0.00111 AU)<br>Outer edge: 175,000 km (0.00117 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "saturn/Saturn: E Ring": "Saturn: E Ring<br><br>Inner edge: 180,000 km (0.00120 AU)<br>Outer edge: 480,000 km (0.00321 AU)<br>Drawn from the served cache; radii as measured.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Magnetopause": "Earth: Magnetopause<br><br>The outer boundary of Earth\'s magnetic field, where it holds off the<br soft>solar wind: pressed in by day, trailing a long tail by night.<br><br>Sunward standoff: 10.3 Earth radii<br>That is about 65,000 km (0.00044 AU). Spacecraft that cross the real<br soft>boundary typically find it within 1.23 Earth radii of this model.<br>Drawn to 120 deg from the nose, as far as the paper plots its model.<br soft>Beyond that angle the boundary is drawn as the magnetotail.<br>Not tilted: the model is symmetric about the Sun line.<br>It is drawn along the line from the Sun to Earth; the real boundary\'s<br soft>nose is turned a few degrees toward the direction Earth moves in its<br soft>orbit, by an amount that depends on the solar wind\'s speed.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Magnetotail": "Earth: Magnetotail<br><br>Earth\'s magnetic field, drawn out by the solar wind into a long tail<br soft>on the night side.<br><br>Spacecraft found the tail stops widening about 120 Earth radii behind<br soft>Earth, plus or minus 10, and is about 60 Earth radii wide beyond<br soft>there, plus or minus 5.<br>That is about 800,000 km (0.005 AU) and 400,000 km (0.003 AU).<br>The straight widening up to that point is our choice; the measurements<br soft>give only its two ends.<br>The drawing stops at 220 Earth radii, which is how far the spacecraft<br soft>went, not where the tail ends.<br>Drawn round, its average shape; at any moment it is often flattened.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Bow Shock": "Earth: Bow Shock<br><br>The shock wave where the supersonic solar wind first slows as it hits<br soft>Earth\'s magnetic field, like the bow wave of a boat.<br><br>Sunward standoff: 13.5 Earth radii<br>That is about 86,000 km (0.00058 AU). Spacecraft that cross the real<br soft>shock typically find it within 0.69 Earth radii of this model.<br>Drawn to 105 deg from the nose, which is how far round the crossings<br soft>the fit was made from actually reached.<br>Not tilted: the fit is symmetric about the Sun line.<br>It is drawn along the line from the Sun to Earth; the real shock\'s<br soft>nose is turned a few degrees toward the direction Earth moves in its<br soft>orbit, by an amount that depends on the solar wind\'s speed.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Inner Radiation Belt": "Earth: Inner Radiation Belt<br><br>A belt of trapped charged particles, mostly protons, held by Earth\'s<br soft>magnetic field close above the atmosphere.<br><br>The belt is one continuous region. Its dots follow Earth\'s magnetic<br soft>field lines, which curve from the equator down toward the ground, and<br soft>they are thickest where the belt is most intense. How they thin out is<br soft>drawn to show the shape, not measured.<br>Thickest at 1.5 Earth radii from Earth\'s centre, at the magnetic<br soft>equator: near where the measured flux of trapped protons is greatest.<br>= 9,600 km (0.00006 AU)<br>Measured extent: 1.1 to 2 Earth radii<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "earth/Earth: Outer Radiation Belt": "Earth: Outer Radiation Belt<br><br>A broader belt of trapped electrons farther out, that swells and<br soft>shrinks with solar storms.<br><br>The belt is one continuous region. Its dots follow Earth\'s magnetic<br soft>field lines, which curve from the equator down toward the ground, and<br soft>they are thickest where the belt is most intense. How they thin out is<br soft>drawn to show the shape, not measured.<br>Thickest at 4.5 Earth radii: halfway across the band, 4 to 5 Earth<br soft>radii out at the magnetic equator, where the belt is most intense. The<br soft>halfway point is our choice for the picture, not a measured peak.<br>Measured extent: 3 to 7 Earth radii<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/moon": "Moon (osculating orbit)<br>r = 0.002383 AU (3.566e+05 km)<br>x = -0.000596 AU, y = 0.002303 AU, z = 0.000145 AU",\n "scene/moon#2": "Moon<br>r = 0.002705 AU (4.046e+05 km)<br>x = 0.000238 AU, y = -0.002688 AU, z = -0.000191 AU",\n "scene/moon#3": "Moon",\n "scene/Earth: Rotation Axis and Equator": "<b>Earth: Rotation Axis and Equator</b><br><br>North pole up the gold line; the ring is the equator on the crust.<br>Tilt: [the served tilt of date, graded above], measured against the orbit of the<br soft>Earth-Moon barycenter, the gravitational center of the Earth-Moon<br soft>system, around the Sun that day (JPL Horizons).<br>The axis slowly circles over thousands of years and nods slightly, so<br soft>the pole and the tilt belong to that date.<br>Axis drawn to 7,827 km (0.0000523 AU) -- a drawing length.<br>The curved arrows at both ends show the sense of the turning:<br soft>prograde, west to east, counter-clockwise seen from above the north<br soft>pole. Earth turns once every 23.93447 hours measured against the<br soft>stars. The turning is not animated, because nothing on the crust marks<br soft>a longitude to watch it by.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/Earth: Sun Direction": "<b>Earth: Sun Direction</b><br><br>Toward the Sun at 2026-09-09, from Earth\'s centre.<br>The dot where the line leaves the crust is the subsolar point, where<br soft>the Sun is overhead.<br>Earth-Sun distance: 149,117,173 km (0.997 AU)<br>Line drawn to the edge of the arrival frame; the Sun is far beyond it.<br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/Earth: Terminator (day-night line)": "<b>Earth: Terminator (day-night line)</b><br><br>The white circle is where the Sun is on the horizon: the sunlit half<br soft>of Earth faces the Sun line, the night half faces away. The yellow<br soft>line through the circle\'s centre is the Sun direction; its dot on the<br soft>crust is the subsolar point, where the Sun is overhead.<br><br>FROZEN at 2026-09-09. The real terminator sweeps around Earth once a<br soft>day; this scene does not turn. Geometry only -- no lighting is<br soft>modelled, and the refraction and solar-disc corrections that define<br soft>sunrise on the ground are not applied.<br><br><br><br>For more information and references please click on the<br soft>info \\"i\\" button top right.",\n "scene/moon#4": "<b>Moon: trusted arc of the orbit</b><br><br>The brighter arc is the part of the Moon\'s orbit where this page\'s<br soft>propagation is trusted to within 0.5 deg: 3.36 days either side of the<br soft>elements\' epoch.<br>The arc runs from 2026-10-13 15:00 to 2026-10-20 08:00 (UTC).<br>There is no longer span to choose: this scene is one epoch, and the<br soft>arc is the stretch of orbit the served elements are trusted for.<br>The faint full ellipse is the same orbit swept once around; outside<br soft>the arc, the Moon\'s real path drifts from it as the Sun and Earth\'s<br soft>shape perturb the two-body orbit.<br><br><br><br>For more information and references please click on the<br soft>info \\"i\\" button top right."\n}\n'}


def main():
    texts, crlf = {}, {}
    for path, want in FINGERPRINTS.items():
        try:
            with open(path, 'rb') as f:
                raw = f.read()
        except OSError as e:
            print('ERROR: cannot read %s (%s). Run from the folder this patch '
                  'names. NOTHING was written.' % (path, e))
            return 1
        crlf[path] = b'\r\n' in raw
        text = raw.replace(b'\r\n', b'\n').decode('utf-8')
        got = hashlib.md5(text.encode('utf-8')).hexdigest()
        if got != want:
            print('ERROR: %s is not the file this patch was built on '
                  '(fingerprint %s, expected %s). NOTHING was written.'
                  % (path, got, want))
            return 1
        texts[path] = text
    import os
    for path, body in NEW_FILES.items():
        if os.path.exists(path):
            with open(path, 'rb') as f:
                have = f.read().replace(b'\r\n', b'\n').decode('utf-8')
            if have != body:
                print('ERROR: %s already exists with other content. NOTHING '
                      'was written.' % path)
                return 1
    out = {}
    for path, pairs in EDITS.items():
        t = texts[path]
        for i, (old, new) in enumerate(reversed(pairs)):
            n = t.count(old)
            if n != 1:
                print('ANCHOR FAIL: %s edit %d matched %d times. NOTHING was '
                      'written.' % (path, len(pairs) - i, n))
                return 1
            t = t.replace(old, new)
        before = set(texts[path].split('\n'))
        bad = [x for x in t.split('\n') if x not in before and any(ord(c) > 127 for c in x)]
        if bad:
            print('ERROR: a line this patch inserts in %s is not ASCII. NOTHING '
                  'was written.' % path)
            return 1
        out[path] = t
        print('ok  %s: %d edit(s)' % (path, len(pairs)))
    for path, t in out.items():
        with open(path, 'wb') as f:
            f.write(t.encode('utf-8'))
        if crlf[path]:
            print('note: %s was CRLF in the working copy; written LF' % path)
    for path, body in NEW_FILES.items():
        with open(path, 'wb') as f:
            f.write(body.encode('utf-8'))
        print('ok  wrote %s' % path)
    print(AFTER)
    print('patch applied')
    return 0


if __name__ == '__main__':
    sys.exit(main())
